    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length < 2) return;

    const N = BigInt(input[0]);
    const T = parseInt(input[1], 10);

    let ans;
    if (T === 0) {
        ans = N;
    } else if (T === 1) {
        ans = N * (N - 1n);
